import assert from 'node:assert/strict';
import { test } from 'node:test';
import { createMtqgClient } from '../../../../src/mtqg/client';
import type { GlossaryRecord } from '../../../../src/mtqg/types';
import { renderGlossary } from '../../../../src/webview/screens/glossary';
import { createTempRepo } from '../../../helpers/tempRepo';

function entry(id: string, word: string, text: string, created: string): GlossaryRecord {
  return { id, kind: 'glossary', word, text, author: { kind: 'human', name: 'test' }, created, updated: created };
}

function rowHtml(html: string, id: string): string {
  const match = html.match(new RegExp(`<tr data-id="${id}">[\\s\\S]*?</tr>`));
  if (!match) {
    throw new Error(`row ${id} not found in:\n${html}`);
  }
  return match[0];
}

test('renderGlossary sorts newest-first by created', () => {
  const html = renderGlossary([
    entry('a', 'alpha', 'first', '2026-01-01T00:00:00Z'),
    entry('b', 'beta', 'second', '2026-02-01T00:00:00Z'),
  ]);
  const order = [...html.matchAll(/data-id="(a|b)"/g)].map((m) => m[1]);
  assert.deepEqual(order, ['b', 'a']);
});

test('renderGlossary flags every entry that shares a word with a badge, not color alone', () => {
  const html = renderGlossary([
    entry('a', 'token', 'first definition', '2026-01-01T00:00:00Z'),
    entry('b', 'token', 'second definition', '2026-02-01T00:00:00Z'),
    entry('c', 'unique', 'only definition', '2026-03-01T00:00:00Z'),
  ]);
  assert.match(rowHtml(html, 'a'), /dup-badge/);
  assert.match(rowHtml(html, 'b'), /dup-badge/);
  assert.doesNotMatch(rowHtml(html, 'c'), /dup-badge/);
});

test('renderGlossary makes the definition editable but never the word (mtqg edit cannot change it)', () => {
  const row = rowHtml(renderGlossary([entry('a', 'token', 'a definition', '2026-01-01T00:00:00Z')]), 'a');
  assert.doesNotMatch(row, /data-field="word"/);
  assert.match(row, /data-field="text"/);
});

test('renderGlossary gives each row a Copy ID button next to the delete button', () => {
  const row = rowHtml(renderGlossary([entry('a', 'token', 'a definition', '2026-01-01T00:00:00Z')]), 'a');
  assert.match(row, /data-action="copy-id"/);
});

test('the add row lets a new term and definition be typed', () => {
  const html = renderGlossary([]);
  assert.match(html, /class="add-row"/);
  assert.match(html, /data-field="word"/);
  assert.match(html, /data-field="text"/);
});

test('a real glossary entry added through mtqg renders with its word and definition', async () => {
  const repo = await createTempRepo();
  try {
    const client = createMtqgClient(repo.root);
    const added = await client.glossaryAdd('token', 'The smallest unit produced by lexing');
    // Exact equality on the record itself (not just a substring match on
    // the rendered HTML): catches a stray separator prepended to the
    // definition (the client.ts `glossaryAdd` bug found via this todo's
    // manual check -- a substring match here would not have caught it).
    assert.equal(added.data.record.text, 'The smallest unit produced by lexing');
    const html = renderGlossary([added.data.record]);
    assert.match(html, /token/);
    assert.match(html, /The smallest unit produced by lexing/);
  } finally {
    await repo.cleanup();
  }
});

import type { RuleRecord } from '../../mtqg/types';
import { authorCell, copyIdButtonCell, dateCell, deleteButtonCell, editableCell } from './table';

/**
 * `rule list` does not guarantee any particular order (verified against the
 * real binary: three rules added in sequence came back as third/first/second
 * -- it appears to be ID order). The newest-first order decided for this
 * screen (q&a `e07736f680`) is therefore built here from `created`, not
 * inherited from mtqg's own response.
 */
export function renderRules(records: RuleRecord[]): string {
  const sorted = [...records].sort((a, b) => b.created.localeCompare(a.created));
  const rows = sorted
    .map(
      (r) =>
        `<tr data-id="${r.id}">${editableCell('text', r.text)}${authorCell(r.author)}${dateCell(r.created)}${copyIdButtonCell(r.id)}${deleteButtonCell()}</tr>`,
    )
    .join('');

  return `<table class="mtqg-table">
  <thead><tr><th>Text</th><th>Author</th><th>Date</th><th></th><th></th></tr></thead>
  <tbody>
    <tr class="add-row">${editableCell('text', '', 'New rule text')}<td></td><td></td><td></td><td></td></tr>
    ${rows}
  </tbody>
</table>`;
}

import type { GlossaryRecord } from '../../mtqg/types';
import { escapeHtml } from '../shared/escape';
import { authorCell, copyIdButtonCell, dateCell, deleteButtonCell, editableCell } from './table';

/**
 * `edit` can change a glossary entry's definition but never its word
 * (docs/reference/cli.md「edit, delete」: "The word of a glossary entry
 * cannot [change]"), so unlike `renderRules`, only the definition column is
 * `editableCell` on an existing row -- the word is editable only on the add
 * row, where it is still being created.
 *
 * Same-word entries are flagged with a badge, not sorted next to each other:
 * the human chose newest-first order for this screen over grouping by word
 * (q&a `e07736f680`), so "並べて目立たせる" (ui.md) is done visually instead.
 */
export function renderGlossary(records: GlossaryRecord[]): string {
  const sorted = [...records].sort((a, b) => b.created.localeCompare(a.created));
  const wordCounts = new Map<string, number>();
  for (const record of sorted) {
    wordCounts.set(record.word, (wordCounts.get(record.word) ?? 0) + 1);
  }

  const rows = sorted
    .map((r) => {
      const isDuplicate = (wordCounts.get(r.word) ?? 0) > 1;
      const badge = isDuplicate
        ? ' <span class="dup-badge" title="This term has more than one definition">⚠ dup</span>'
        : '';
      const wordCell = `<td class="${isDuplicate ? 'duplicate' : ''}">${escapeHtml(r.word)}${badge}</td>`;
      return `<tr data-id="${r.id}">${wordCell}${editableCell('text', r.text)}${authorCell(r.author)}${dateCell(r.created)}${copyIdButtonCell(r.id)}${deleteButtonCell()}</tr>`;
    })
    .join('');

  return `<table class="mtqg-table">
  <thead><tr><th>Word</th><th>Definition</th><th>Author</th><th>Date</th><th></th><th></th></tr></thead>
  <tbody>
    <tr class="add-row">${editableCell('word', '', 'New term')}${editableCell('text', '', 'New definition')}<td></td><td></td><td></td><td></td></tr>
    ${rows}
  </tbody>
</table>`;
}

import type { TodoRecord } from '../../mtqg/types';
import { escapeHtml } from '../shared/escape';
import { authorText, copyIdButton, dateText, deleteButton, editableElement } from './table';

export interface TodosView {
  /** "Show done" checkbox state (ui.md: default is open-only). */
  all?: boolean;
}

/**
 * One card. Checking/unchecking the checkbox sends `setStatus` (kind
 * independent of the record's own text edits, which go through the
 * shared `editRecord` message). Done is shown with both a checked box and
 * a strikethrough on the text -- never colour alone (ui.md「色だけで意味を
 * 伝えない」).
 */
function card(record: TodoRecord): string {
  const done = record.status === 'done';
  const checkboxLabel = done ? 'Reopen' : 'Mark done';
  return `<article class="card${done ? ' done' : ''}" data-id="${record.id}">
    <label class="card-check">
      <input type="checkbox" data-action="toggle-status" aria-label="${checkboxLabel}"${done ? ' checked' : ''}>
    </label>
    ${editableElement('div', 'text', record.text)}
    <div class="card-meta">
      <span>${escapeHtml(authorText(record.author))}</span>
      <span>${escapeHtml(dateText(record.created))}</span>
    </div>
    <div class="card-actions">${copyIdButton(record.id)}${deleteButton()}</div>
  </article>`;
}

/**
 * `todo list` does not guarantee any particular order (verified against
 * the real binary, same finding as `rule list`/`glossary list` --
 * `.claude/rules/mtqg-cli.md`), so newest-first (q&a `e07736f680`, reused
 * here) is built from `created`.
 */
function sortedByCreated(records: TodoRecord[]): TodoRecord[] {
  return [...records].sort((a, b) => b.created.localeCompare(a.created));
}

/**
 * Renders the ToDo screen: an add field, a "Show done" toggle, and a grid
 * of cards. When `all` is false (the default, ui.md), only open todos are
 * shown and the toggle reflects that no done ones are hidden-but-zero vs
 * hidden-and-some -- the count is always the true total so switching the
 * toggle never looks like it did nothing.
 */
export function renderTodos(records: TodoRecord[], view: TodosView = {}): string {
  const open = sortedByCreated(records.filter((r) => r.status === 'open'));
  const done = sortedByCreated(records.filter((r) => r.status === 'done'));
  const all = view.all ?? false;

  const openCards = open.map(card).join('');
  const doneSection = all
    ? `<h3 class="done-heading">Done (${done.length})</h3><div class="mtqg-cards">${done.map(card).join('')}</div>`
    : '';

  return `<div class="screen-toolbar">
  <div class="add-row">${editableElement('div', 'text', '', 'New todo…')}</div>
  <label><input type="checkbox" data-action="show-all"${all ? ' checked' : ''}> Show done (${done.length})</label>
</div>
<div class="mtqg-cards">${openCards}</div>
${doneSection}`;
}

